            self._respond(200, {"status": "ok"})
        elif self.path == "/v1/keys":
            self._respond(200, {"keys": self.store.keys()})
        elif (key := route_key(self.path)) is not None:
            value = self.store.get(key)
            self._respond(404, {"error": "key not found"}) if value is None else self._respond(200, {"key": key, "value": value})
        else:
            self._error(404, "route not found")

    def do_PUT(self):
        key = route_key(self.path)
        if key is None:
            self._error(400 if self.path.startswith("/v1/kv/") else 404, "invalid key" if self.path.startswith("/v1/kv/") else "route not found")
            return
        data = self._read_json()
        if data is None:
            return
        if not isinstance(data, dict) or "value" not in data or set(data) - {"value", "ttl_seconds"}:
            self._error(400, "body must contain value and optional ttl_seconds")
            return
        ttl = data.get("ttl_seconds")
        if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0):
            self._error(400, "ttl_seconds must be a finite positive number")
            return
        try:
            self._respond(201 if self.store.put(key, data["value"], ttl) else 200, {"key": key, "value": data["value"]})
        except (OSError, TypeError, ValueError) as exc:
            print(f"persistence error: {exc}", file=sys.stderr, flush=True)
            self._error(500, "persistence failure")

    def do_DELETE(self):
        key = route_key(self.path)
        if key is None:
            self._error(400 if self.path.startswith("/v1/kv/") else 404, "invalid key" if self.path.startswith("/v1/kv/") else "route not found")
        elif self.store.delete(key):
            self._respond(204)
        else:
            self._error(404, "key not found")

    def do_POST(self): self._error(405, "method not allowed")
    def do_PATCH(self): self._error(405, "method not allowed")
    def do_HEAD(self): self._error(405, "method not allowed")


def run_server(host: str, port: int, data: str) -> None:
    Handler.store = Store(data)
    server = ThreadingHTTPServer((host, port), Handler)
    server.daemon_threads = True
    def stop(*_):
        threading.Thread(target=server.shutdown, daemon=True).start()
    signal.signal(signal.SIGTERM, stop)
    print(f"LISTENING {server.server_port}", flush=True)
    try:
        server.serve_forever()
    finally:
        server.server_close()


class ServiceTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        Handler.store = Store(str(Path(self.temp.name) / "data.json"))
        self.server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()
    def tearDown(self):
        self.server.shutdown(); self.server.server_close(); self.temp.cleanup()
    def request(self, method, path, body=None):
        conn = HTTPConnection("127.0.0.1", self.server.server_port)
        conn.request(method, path, body, {"Content-Type": "application/json"} if body else {})
        response = conn.getresponse(); result = response.read(); conn.close()
        return response.status, json.loads(result) if result else None
    def test_crud_ttl_and_persistence(self):
        self.assertEqual(self.request("PUT", "/v1/kv/a%20b", '{"value":[1],"ttl_seconds":1}')[0], 201)
        self.assertEqual(self.request("GET", "/v1/kv/a%20b")[1]["value"], [1])
        self.assertEqual(self.request("GET", "/v1/keys")[1], {"keys": ["a b"]})
        self.assertEqual(self.request("DELETE", "/v1/kv/a%20b")[0], 204)
        self.assertEqual(self.request("GET", "/v1/kv/a%20b")[0], 404)
    def test_validation(self):
        self.assertEqual(self.request("PUT", "/v1/kv/x", '{"value":1,"ttl_seconds":0}')[0], 400)
        self.assertEqual(self.request("PUT", "/v1/kv/x", "[")[0], 400)
        self.assertEqual(self.request("POST", "/health")[0], 405)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--data", default="data.json")
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    if args.self_test:
        unittest.main(argv=[sys.argv[0]])
    else:
        run_server(args.host, args.port, args.data)

if __name__ == "__main__":
    main()

