from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote

MAX_BODY = 1024 * 1024
MISSING = object()


class Store:
    def __init__(self, filename: str):
        self.path = Path(filename)
        self.lock = threading.RLock()
        self.entries: dict[str, dict] = {}
        self._load()

    def _load(self) -> None:
        try:
            with self.path.open(encoding="utf-8") as source:
                raw = json.load(source)
            if not isinstance(raw, dict):
                raise ValueError("top-level data is not an object")
            for key, entry in raw.items():
                if isinstance(key, str) and isinstance(entry, dict) and "value" in entry:
                    expiry = entry.get("expires_at")
                    if expiry is None or (isinstance(expiry, (int, float)) and math.isfinite(expiry)):
                        self.entries[key] = {"value": entry["value"], "expires_at": expiry}
        except FileNotFoundError:
            return
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            print(f"warning: cannot load data file: {exc}", file=sys.stderr, flush=True)
        self._purge_locked(persist=False)

    def _purge_locked(self, persist: bool = True) -> bool:
        now = time.time()
        dead = [key for key, entry in self.entries.items()
                if entry["expires_at"] is not None and entry["expires_at"] <= now]
        for key in dead:
            del self.entries[key]
        if dead and persist:
            self._save_locked()
        return bool(dead)

    def _save_locked(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = json.dumps(self.entries, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
        fd, temp_name = tempfile.mkstemp(prefix=f".{self.path.name}.", suffix=".tmp", dir=self.path.parent)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as target:
                target.write(payload)
                target.flush()
                os.fsync(target.fileno())
            os.replace(temp_name, self.path)
        except Exception:
            try:
                os.unlink(temp_name)
            except FileNotFoundError:
                pass
            raise

    def get(self, key: str):
        with self.lock:
            self._purge_locked()
            entry = self.entries.get(key)
            return MISSING if entry is None else entry["value"]

    def put(self, key: str, value, ttl: float | None) -> bool:
        with self.lock:
            self._purge_locked()
            created = key not in self.entries
            self.entries[key] = {"value": value, "expires_at": None if ttl is None else time.time() + ttl}
            self._save_locked()
            return created

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge_locked()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._save_locked()
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._purge_locked()
            return sorted(self.entries)


def route_key(path: str) -> str | None:
    prefix = "/v1/kv/"
    if not path.startswith(prefix):
        return None
    encoded = path[len(prefix):]
    if not encoded or "/" in encoded:
        return None
    try:
        key = unquote(encoded, encoding="utf-8", errors="strict")
    except UnicodeDecodeError:
        return None
    return key if key and "/" not in key else None


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    store: Store

    def log_message(self, fmt, *args):
        print(f"{self.client_address[0]} - {fmt % args}", file=sys.stderr, flush=True)

    def _respond(self, status: int, body=None) -> None:
        content = b"" if body is None else json.dumps(body, ensure_ascii=False, allow_nan=False).encode("utf-8")
        self.send_response(status)
        if body is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(content)))
        self.end_headers()
        if content:
            self.wfile.write(content)

    def _error(self, status: int, message: str) -> None:
        self._respond(status, {"error": message})

    def _read_json(self):
        length = self.headers.get("Content-Length")
        if length is None:
            self._error(411, "Content-Length required")
            return None
        try:
            size = int(length)
        except ValueError:
            self._error(400, "invalid Content-Length")
            return None
        if size < 0:
            self._error(400, "invalid Content-Length")
            return None
        if size > MAX_BODY:
            self._error(413, "request body too large")
            return None
        try:
            return json.loads(self.rfile.read(size).decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._error(400, "malformed JSON")
            return None

    def do_GET(self):
        if self.path == "/health":
            self._respond(200, {"status": "ok"})
        elif self.path == "/v1/keys":
            self._respond(200, {"keys": self.store.keys()})
        elif (key := route_key(self.path)) is not None:
            value = self.store.get(key)
            self._respond(404, {"error": "key not found"}) if value is MISSING else self._respond(200, {"key": key, "value": value})
        else:
            self._error(404, "route not found")

